SELECT `tenantId` AS `tenantId`, `entityId` AS `entityId`, ifNull(`category`, {p0:String}) AS `category`, `state` AS `state`, `part_specifications` AS `part_specifications`, `matched_part_ids` AS `matched_part_ids`, `countOfParts` AS `countOfParts`, `updatedAt` AS `updatedAt`, length(`matched_part_ids`) AS `matched`, tupleElement(`part_specifications`, {p1:String}) AS `mpns`, tupleElement(arrayElement(`part_specifications`, {p2:Int64}), {p3:String}) AS `firstDesc`, dateDiff({p4:String}, `updatedAt`, now(), {p5:String}) AS `age`, multiIf(`countOfParts` = {p6:UInt64}, {p7:String}, `countOfParts` < {p8:UInt64}, {p9:String}, {p10:String}) AS `tier`, {p11:String} AS `source` FROM `entity_ots_component`
